package test

import (
	"testing"

	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"
)

// These tests exercise the Copy()/CopyFrom() methods generated by
// protoc-gen-goswarm's deepcopy plugin. For each message shape they assert two
// properties:
//
//  1. The copy is logically equal to the original (proto.Equal).
//  2. The copy is a *deep* copy: mutating the copy's nested/reference fields
//     does not affect the original.

func fullBasicScalar() *BasicScalar {
	return &BasicScalar{
		Field1:  1.5,
		Field2:  2.5,
		Field3:  3,
		Field4:  4,
		Field5:  5,
		Field6:  6,
		Field7:  7,
		Field8:  8,
		Field9:  9,
		Field10: 10,
		Field11: 11,
		Field12: 12,
		Field13: true,
		Field14: "fourteen",
		Field15: []byte("fifteen"),
	}
}

func fullRepeatedScalar() *RepeatedScalar {
	return &RepeatedScalar{
		Field1:  []float64{1, 2},
		Field2:  []float32{3, 4},
		Field3:  []int32{5, 6},
		Field4:  []int64{7, 8},
		Field5:  []uint32{9, 10},
		Field6:  []uint64{11, 12},
		Field7:  []int32{13, 14},
		Field8:  []int64{15, 16},
		Field9:  []uint32{17, 18},
		Field10: []int32{19, 20},
		Field11: []uint64{21, 22},
		Field12: []int64{23, 24},
		Field13: []bool{true, false},
		Field14: []string{"a", "b"},
		Field15: [][]byte{[]byte("x"), []byte("y")},
	}
}

func fullRepeatedScalarPacked() *RepeatedScalarPacked {
	return &RepeatedScalarPacked{
		Field1:  []float64{1, 2},
		Field2:  []float32{3, 4},
		Field3:  []int32{5, 6},
		Field4:  []int64{7, 8},
		Field5:  []uint32{9, 10},
		Field6:  []uint64{11, 12},
		Field7:  []int32{13, 14},
		Field8:  []int64{15, 16},
		Field9:  []uint32{17, 18},
		Field10: []int32{19, 20},
		Field11: []uint64{21, 22},
		Field12: []int64{23, 24},
		Field13: []bool{true, false},
	}
}

func TestBasicScalarCopy(t *testing.T) {
	in := fullBasicScalar()
	out := in.Copy()
	require.True(t, proto.Equal(in, out))

	// bytes must be a distinct backing array
	require.NotSame(t, &in.Field15[0], &out.Field15[0])
	out.Field15[0] = 'Z'
	require.Equal(t, byte('f'), in.Field15[0], "mutating copy must not affect original")
}

func TestRepeatedScalarCopy(t *testing.T) {
	in := fullRepeatedScalar()
	out := in.Copy()
	require.True(t, proto.Equal(in, out))

	// scalar slices must be distinct backing arrays
	out.Field3[0] = 999
	require.Equal(t, int32(5), in.Field3[0])

	// repeated bytes must be deeply independent
	out.Field15[0][0] = 'Z'
	require.Equal(t, byte('x'), in.Field15[0][0])
}

func TestRepeatedScalarPackedCopy(t *testing.T) {
	in := fullRepeatedScalarPacked()
	out := in.Copy()
	require.True(t, proto.Equal(in, out))

	out.Field1[0] = 999
	require.Equal(t, float64(1), in.Field1[0])
}

func TestExternalStructCopy(t *testing.T) {
	in := &ExternalStruct{
		Field1: fullBasicScalar(),
		Field2: fullRepeatedScalar(),
		Field3: fullRepeatedScalarPacked(),
	}
	out := in.Copy()
	require.True(t, proto.Equal(in, out))

	// nested message pointers must differ
	require.NotSame(t, in.Field1, out.Field1)
	out.Field1.Field3 = 12345
	require.Equal(t, int32(3), in.Field1.Field3, "mutating nested copy must not affect original")
}

func TestRepeatedExternalStructCopy(t *testing.T) {
	in := &RepeatedExternalStruct{
		Field1: []*BasicScalar{fullBasicScalar(), fullBasicScalar()},
		Field2: []*RepeatedScalar{fullRepeatedScalar()},
		Field3: []*RepeatedScalarPacked{fullRepeatedScalarPacked()},
	}
	out := in.Copy()
	require.True(t, proto.Equal(in, out))

	require.NotSame(t, in.Field1[0], out.Field1[0])
	out.Field1[0].Field3 = 12345
	require.Equal(t, int32(3), in.Field1[0].Field3)
}

func TestMapStructCopy(t *testing.T) {
	in := &MapStruct{
		NullableMap: map[string]*BasicScalar{
			"a": fullBasicScalar(),
		},
		ScalarMap: map[string]string{"k": "v"},
		BytesMap:  map[string][]byte{"b": []byte("data")},
	}
	out := in.Copy()
	require.True(t, proto.Equal(in, out))

	// message map values must be deeply independent
	require.NotSame(t, in.NullableMap["a"], out.NullableMap["a"])
	out.NullableMap["a"].Field3 = 12345
	require.Equal(t, int32(3), in.NullableMap["a"].Field3)

	// scalar map must be a distinct map
	out.ScalarMap["k"] = "changed"
	require.Equal(t, "v", in.ScalarMap["k"])

	// bytes map values must be deeply independent
	out.BytesMap["b"][0] = 'Z'
	require.Equal(t, byte('d'), in.BytesMap["b"][0])
}

func TestOneOfCopy(t *testing.T) {
	cases := []struct {
		name string
		in   *OneOf
	}{
		{"scalar", &OneOf{Fields: &OneOf_Field3{Field3: 42}}},
		{"bytes", &OneOf{Fields: &OneOf_Field7{Field7: []byte("payload")}}},
		{"message", &OneOf{Fields: &OneOf_Field8{Field8: &MapStruct{
			NullableMap: map[string]*BasicScalar{"a": fullBasicScalar()},
		}}}},
		{"repeated", &OneOf{Fields: &OneOf_Field9{Field9: &RepeatedExternalStruct{
			Field1: []*BasicScalar{fullBasicScalar()},
		}}}},
		{"fieldsTwo-message", &OneOf{FieldsTwo: &OneOf_Field10{Field10: &ExternalStruct{
			Field1: fullBasicScalar(),
		}}}},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			out := tc.in.Copy()
			require.True(t, proto.Equal(tc.in, out))
		})
	}

	// Verify deep independence of a oneof-wrapped bytes field.
	in := &OneOf{Fields: &OneOf_Field7{Field7: []byte("payload")}}
	out := in.Copy()
	out.GetField7()[0] = 'Z'
	require.Equal(t, byte('p'), in.GetField7()[0])

	// Verify deep independence of a oneof-wrapped message field.
	in = &OneOf{Fields: &OneOf_Field8{Field8: &MapStruct{
		NullableMap: map[string]*BasicScalar{"a": fullBasicScalar()},
	}}}
	out = in.Copy()
	out.GetField8().NullableMap["a"].Field3 = 12345
	require.Equal(t, int32(3), in.GetField8().NullableMap["a"].Field3)
}

func TestCopyNilReturnsNil(t *testing.T) {
	var bs *BasicScalar
	require.Nil(t, bs.Copy())

	var es *ExternalStruct
	require.Nil(t, es.Copy())

	var oneof *OneOf
	require.Nil(t, oneof.Copy())
}
